select id, customer_id, start_date, end_date, lag(monthly_fee) over (partition by customer_id order by end_date, id) as prev_monthly_fee, lead(monthly_fee) over (partition by customer_id order by end_date, id) as next_monthly_fee, row_number() over (partition by customer_id order by end_date, id) as event_seq, sum(monthly_fee) over (order by start_date, id rows between unbounded preceding and current row) as running_monthly_fee from subscriptions
